 public static void Automatic(){try{using(var e=new Engine()){e.Sync=true;e.BPM=300;e.Bars=1;e.AutoOverdub=true;var route=new Input(new SourceChoice{Name="Live",Left=0,Right=1});e.Inputs.Add(route);e.Begin(false);int period=Engine.MeasureFrames(300,4,4,1);var block=new float[514];var output=new float[514];int chunks=0;while(e.AudioFrame<period*2+2000){long start=e.AudioFrame;for(int i=0;i<257;i++)block[i*2]=block[i*2+1]=.1f+.05f*((start+i)/period);route.Feed(block,block.Length,2,start);e.Mix(output,257);if(++chunks%13==0)e.DrainCompletedPasses();}e.DrainCompletedPasses();if(e.Layers.Count!=2||!e.Recording||!e.IsOverdubbing)throw new Exception("Auto overdub did not roll into following passes");if(e.Layers[0].Offset!=0||e.Layers[1].Offset!=period||e.Layers[0].Original.Any(x=>Math.Abs(x-.1f)>.000001)||e.Layers[1].Original.Any(x=>Math.Abs(x-.15f)>.000001))throw new Exception("Auto pass lost samples or changed gain at buffer boundary");e.Finish(false);if(e.Recording||e.Layers.Count!=3||e.Layers[2].Offset!=period*2)throw new Exception("Manual stop did not stop Auto Overdub");}
