 public static void NativeLive(){try{var source=new float[96000];for(int i=0;i<48000;i++)source[i*2]=source[i*2+1]=(float)(.4*Math.Sin(2*Math.PI*440*i/48000));using(var stream=new LiveStretch(source,1.5,12,false,false,0,0)){var values=new float[96000];var timer=System.Diagnostics.Stopwatch.StartNew();long frame=0;for(int i=0;i<values.Length;i++){float left,right;DateTime deadline=DateTime.UtcNow.AddSeconds(5);while(!stream.TryRead(frame,out left,out right)){if(stream.Error!=null)throw new Exception(stream.Error);if(DateTime.UtcNow>deadline)throw new Exception("Live DSP stalled");Thread.Sleep(1);}values[i]=left;if(float.IsNaN(left)||float.IsInfinity(left)||Math.Abs(left-right)>.00001)throw new Exception("Live output invalid or stereo changed");frame++;}long elapsed=timer.ElapsedMilliseconds;int crossings=0;for(int i=24001;i<72000;i++)if(values[i-1]<=0&&values[i]>0)crossings++;if(Math.Abs(crossings-880)>25||stream.EngineVersion!=3)throw new Exception("Native R3 frequency/engine failed: "+crossings);stream.Configure(source,.75,-12,false,false,frame,0);values=new float[48000];for(int i=0;i<values.Length;i++){float left,right;while(!stream.TryRead(frame,out left,out right)){if(stream.Error!=null)throw new Exception(stream.Error);Thread.Sleep(1);}values[i]=left;frame++;}crossings=0;for(int i=12001;i<36000;i++)if(values[i-1]<=0&&values[i]>0)crossings++;if(Math.Abs(crossings*2-220)>20)throw new Exception("Live parameter change failed: "+crossings*2);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"native-live-tests.txt"),"PASS: native R3 streaming; +12 and -12 semitone changes during playback; independent live stretch; stereo coherence; finite output. Two seconds generated in "+elapsed+" ms.");}}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"native-live-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
