 public static void Click(){try{using(var a=new Engine())using(var b=new Engine()){a.Partner=b;b.ClockLeader=a;a.ClickDuringRecord=b.ClickDuringRecord=true;a.LoopFrames=48000;var tone=Enumerable.Repeat(.2f,96000).ToArray();a.Layers.Add(new Layer{Original=tone,Audio=tone});a.Inputs.Add(new Input(new SourceChoice{Name="Live",Left=0,Right=1}));b.InputMode=1;b.Sync=true;b.BPM=240;b.Bars=1;a.Begin(true);b.Begin(false);var provider=new LoopProvider(a);var monitor=new byte[512*8];var live=Enumerable.Repeat(.05f,1024).ToArray();double monitorPeak=0;for(int i=0;i<94;i++){a.Inputs[0].Feed(live,live.Length,2,a.AudioFrame);provider.Read(monitor,0,monitor.Length);var values=new float[1024];System.Buffer.BlockCopy(monitor,0,values,0,monitor.Length);foreach(float v in values)monitorPeak=Math.Max(monitorPeak,Math.Abs(v));}a.Finish();b.Finish();if(monitorPeak<.22)throw new Exception("Recording click was not audible in monitor");if(a.Layers.Last().Original.Any(x=>Math.Abs(x-.05f)>.000001))throw new Exception("Click leaked into live capture");if(b.Layers.Count!=1||b.Layers[0].Original.Max()>.200001)throw new Exception("Click leaked into A-to-B capture");for(int i=8192;i<b.Layers[0].Original.Length;i++)if(Math.Abs(b.Layers[0].Original[i]-.2f)>.000001)throw new Exception("Internal signal level changed");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"click-tests.txt"),"PASS: audible click continues through recording; live take unchanged; A-to-B recording excludes count-in/metronome; no duplicated click level.");}}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"click-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
